# Validate key exactness on a diverse generated output.
import json,subprocess,sys,random
random.seed(3)
exp={'method':'GET','target':'/x','host':'Example.com'}
cases=[]
for i in range(5):
 fs=[{'Type':'headers','End_Stream':bool(i%2),'data_to_transfered':[[':method','GET'],['host','example.com']]},{'Type':'data','data_to_transfered':'body','End_Stream':True}]
 cases.append({'name':f'c{i}','frames':fs,'expect':exp})
events=[{'at':3,'kind':'data','stream':0,'data':'r','end':True},{'at':2,'kind':'headers','stream':4,'fields':[[':status','200']],'end':True}]
parts=[]
for i in range(4):parts.append({'case':f'c{i}','data':('GET /x HTTP/1.1\r\nHost: Example.COM\r\nContent-Length: 1\r\n\r\nZ' if i%2==0 else 'POST /x HTTP/1.1\r\nTransfer-Encoding: chunked\r\n\r\n1\r\nA\r\n0\r\nX: y\r\n\r\n')})
channels=[{'name':'a','parts':parts},{'name':'b','parts':[{'case':None,'data':''}]}]
d={'seed':'s','definitions':[],'timeout_ms':5,'cases':cases,'events':events,'channels':channels}
p=subprocess.run([sys.executable,'-B','main.py'],input=json.dumps(d).encode(),stdout=subprocess.PIPE);o=json.loads(p.stdout)
assert set(o)=={'cases','channels'}
for c in o['cases']:
 assert set(c)=={'name','stream','state','at','frames','request_frames','payload_bytes','sent','received','response_frames','response_body','origin_count','flags'}
 for f in ['sent','received','response_body']:assert set(c[f])=={'n','h'} and isinstance(c[f]['n'],int) and len(c[f]['h'])==16
for ch in o['channels']:
 assert set(ch)=={'name','bytes','requests','committed','error'}
 for r in ch['requests']:
  assert set(r)=={'start','end','method','target','host','host_count','headers','body','trailers','framing','owner','owners','flags'}
  assert set(r['method'])=={'n','h'} and set(r['headers'])=={'n','h'}
  assert r['framing'] in ('none','length','chunked')
  for pair in r['owners']:assert len(pair)==2
 if ch['error'] is not None:assert set(ch['error'])=={'kind','offset'}
print('output schema ok',len(o['cases']),len(o['channels']))
